from lib import *
recs=[]
recs.append(R(6541800,"بلڈ اورنج سلاد (Insalata D’ Arrance Sangouse)","سسلی اپنے خوبصورت، سرسبز سنگترے کے باغات کے لیے مشہور ہے، جو دنیا کے سب سے خوشبودار سنگتروں میں سے کچھ پیدا کرتے ہیں۔ جزیرے پر عربوں کی حکمرانی کے دوران متعارف کرائے گئے سنگترے کے درخت ماؤنٹ ایٹنا کے دامن میں راکھ میں خوب پھلے پھولے۔ اس ترکیب کے لیے سب سے میٹھے سنگترے تلاش کریں۔ اگر ممکن ہو تو سسلی کے بلڈ اورنج استعمال کریں؛ ان کا سرخ رنگ اس شاندار سلاد کو تہوار کا انداز دیتا ہے۔","6","1/2 کپ",
["4 عدد بلڈ اورنج (کل تقریباً 1 پاؤنڈ، چھلے ہوئے اور گول قتلوں میں کٹے ہوئے)","2 ڈنڈی ہری پیاز (باریک کٹی ہوئی)","1/4 کپ 1 سنگترے کا رس","2 کھانے کے چمچ ایکسٹرا ورجن زیتون کا تیل (ترجیحاً پہلی کولڈ پریسڈ اور بغیر فلٹر کا)","1/4 چائے کا چمچ غیر صاف شدہ سمندری نمک","1/4 چائے کا چمچ کالی مرچ (تازہ پسی ہوئی)","1/8 چائے کا چمچ کٹی ہوئی لال مرچ کے فلیکس"],
["سنگترے کے قتلے ایک بڑے تھال پر رکھیں اور اوپر ہری پیاز بکھیر دیں۔","ایک چھوٹے پیالے میں سنگترے کا رس اور زیتون کا تیل پھینٹ کر ملا لیں، اور نمک، کالی مرچ اور کٹی ہوئی لال مرچ کے فلیکس ڈالیں۔ سلاد پر ڈالیں اور فوراً پیش کریں۔"]))
recs.append(R(6543489,"وہپڈ کاٹیج چیز ڈپ","وہپڈ کاٹیج چیز ڈپ روایتی ڈپس کا ہلکا اور کریمی متبادل ہے، جو ناشتے کے لیے پروٹین سے بھرپور انتخاب فراہم کرتا ہے۔ اسے اپنی پسندیدہ سبزیوں جیسے بروکلی، شملہ مرچ، گاجر اور مزید کے ساتھ نوش کریں!","4","1/3 کپ",
["1 کپ کاٹیج چیز (کم چکنائی والا)","2 کھانے کے چمچ سادہ بغیر چکنائی والا یونانی دہی","1 کھانے کا چمچ لیموں کا رس","2 چائے کے چمچ ورسٹرشائر ساس","1 جوا لہسن (باریک کٹا ہوا)","1 کھانے کا چمچ تازہ چائیوز (کٹے ہوئے)","1/4 چائے کا چمچ کالی مرچ"],
["بلینڈر یا فوڈ پروسیسر میں کم چکنائی والا کاٹیج چیز، یونانی دہی، تازہ لیموں کا رس، ورسٹرشائر ساس اور باریک کٹا لہسن ملائیں۔ اجزاء کو اس وقت تک بلینڈ کریں جب تک ہموار اور کریمی ساخت نہ بن جائے۔ آپ کے بلینڈر یا فوڈ پروسیسر کی طاقت کے لحاظ سے اس میں کچھ منٹ لگ سکتے ہیں۔","جب مرکب ہموار ہو جائے تو اسے ایک پیالے میں منتقل کریں۔ کٹے ہوئے تازہ چائیوز ملا دیں اور وہپڈ کاٹیج چیز ڈپ میں کالی مرچ ڈالیں۔ اچھی طرح ملائیں تاکہ ذائقے برابر پھیل جائیں۔","ذائقے آپس میں مل کر مجموعی ذائقہ بہتر ہو جانے کے لیے ڈپ کو پیش کرنے سے پہلے کم از کم 30 منٹ فریج میں رکھیں۔"]))
recs.append(R(6545397,"بیف اسٹروگینوف","ایک دل بھرنے والی اور لذیذ ڈش تیار کریں جو آپ کی خواہش کو پورا کرے گی اور ساتھ ہی آپ کے خون میں گلوکوز (بلڈ شوگر) کی سطح کو قابو میں رکھنے میں مدد دے گی۔ قدم بہ قدم سیکھیں کہ دبلے گوشت اور صحت بخش اجزاء کے ساتھ ایک کریمی، لذیذ ساس کیسے بنائی جاتی ہے، جو اس ڈش کو مزیدار اور آپ کی صحت کا خیال رکھنے والی بناتی ہے۔ چاہے آپ اپنے لیے پکا رہے ہوں یا اپنے پیاروں کے لیے، یہ ترکیب یقیناً آپ کے باورچی خانے کا مستقل حصہ بن جائے گی۔","5","ترکیب کا 1/5",
["5 اونس سالم اناج کے انڈے والے نوڈلز (کچے)","1 چائے کا چمچ زیتون کا تیل","1 پاؤنڈ بیف ٹینڈرلوئن (0\" ٹرم، 2 انچ کی پٹیوں میں کٹا ہوا)","1 1/2 کپ سفید (بٹن) مشروم (قتلوں میں کٹے ہوئے)","1/2 درمیانی پیاز (باریک کٹی ہوئی)","1 کھانے کا چمچ میدہ (آل پرپز آٹا)","1/4 کپ پانی","1 چائے کا چمچ ڈیجون رائی","14 1/2 اونس بغیر چکنائی اور بغیر نمک اضافے کا بیف شوربہ","1/2 کپ بغیر چکنائی والی کھٹی کریم","1/4 چائے کا چمچ کالی مرچ"],
["نوڈلز کو پیکٹ پر دی گئی ہدایت کے مطابق پکائیں، نمک ڈالے بغیر۔","ایک بڑے سوتے پین میں تیز آنچ پر تیل ڈالیں۔ گوشت ڈالیں اور تقریباً 3 منٹ سوتے کریں۔ گوشت کو پین سے نکال لیں۔ مشروم اور پیاز ڈالیں اور 5 منٹ سوتے کریں یا جب تک وہ بھورا ہونا شروع نہ ہو جائے۔","آٹا ڈالیں اور 1 منٹ پکائیں۔ پین کی تہہ سے لگا ہوا حصہ چھڑانے کے لیے آہستگی سے پانی ڈالیں؛ 2 منٹ پکائیں۔ ڈیجون رائی اور بیف شوربہ ڈالیں؛ ابال لائیں۔ آنچ کم کریں اور 5 منٹ ہلکی آنچ پر پکائیں۔","گوشت اور اس کا رس واپس شوربے میں ڈالیں اور مزید 3 منٹ ہلکی آنچ پر پکائیں۔ کھٹی کریم اور کالی مرچ ڈالیں؛ 30 سیکنڈ ہلکی آنچ پر پکائیں۔","سالم اناج کے انڈے والے نوڈلز کے اوپر پیش کریں۔"]))
recs.append(R(6545769,"صحت بخش اسنیک مکس — فوڈی ترکیب","یہ اسنیک مکس بہت سے میوؤں اور بیجوں سے غذائیت اور صحت بخش چکنائی سے بھرپور ہے۔ مزید یہ کہ فریز ڈرائیڈ بلیو بیریز مکس میں کھٹا، پھلوں جیسا ذائقہ شامل کرتی ہیں!","15","1/4 کپ",
["1 اسپرے، 0.25 گرام نان اسٹک کوکنگ اسپرے","2 کھانے کے چمچ کم کیلوری والا براؤن شوگر متبادل","1/8 چائے کا چمچ کیین مرچ","1 کپ بغیر نمک کے کدو کے بیج (کچے، پیپیٹاس)","1 کپ بغیر نمک کے سورج مکھی کے بیج","1 کپ بغیر نمک کے کٹے ہوئے بادام","1/4 کپ تل","1 اونس فریز ڈرائیڈ بلیو بیریز"],
["اوون کو 300 ڈگری F پر پہلے سے گرم کریں۔","بیکنگ شیٹ پر نان اسٹک کوکنگ اسپرے لگائیں اور ایک طرف رکھ دیں۔","ایک پیالے میں براؤن شوگر متبادل، کیین مرچ، کدو کے بیج، سورج مکھی کے بیج، بادام اور تل ملائیں۔ سب پر لگانے کے لیے ملا دیں۔","آمیزہ بیکنگ شیٹ پر پھیلا دیں اور پھر کوکنگ اسپرے کی ہلکی تہہ کے ساتھ دوبارہ اسپرے کریں۔","15 منٹ بیک کریں، ہر 5 منٹ بعد ہلاتے رہیں تاکہ برابر بھورا ہو۔","اوون سے نکالیں اور ٹھنڈا ہونے کے لیے ایک طرف رکھ دیں۔ ٹھنڈا ہونے پر میوں کے مرکب کو پیالے میں فریز ڈرائیڈ بلیو بیریز کے ساتھ ملا دیں۔"]))
recs.append(R(6548283,"لذیذ سی ویڈ ایڈامامے دہی کا باؤل","یہ لذیذ دہی کا باؤل کریمی بغیر چکنائی والا یونانی دہی، نرم ایڈامامے اور بھنے ہوئے سی ویڈ کی نمکین کرکراہٹ کو یکجا کرتا ہے، تاکہ زیادہ پروٹین والا، ذائقے سے بھرپور ناشتہ بنے۔ یہ فوری، تازگی بخش ہے اور بغیر پکائے سوشی سے متاثر انداز فراہم کرتا ہے۔","1","1 1/2 کپ",
["1 کپ سادہ بغیر چکنائی والا یونانی دہی","1 پیکٹ بھنا ہوا سی ویڈ","1/2 کپ چھلکا اتارا ہوا ایڈامامے"],
["1 کپ بغیر چکنائی والا یونانی دہی ایک چھوٹے پیالے میں ڈالیں۔","1/2 کپ چھلکا اتارا ہوا ایڈامامے ڈال کر برابر پھیلنے تک ہلائیں۔","بھنے ہوئے سی ویڈ کا پیکٹ اوپر سے چورا کر کے ڈالیں یا نرم ساخت کے لیے ملا دیں۔","فوراً پیش کریں تاکہ سی ویڈ کرکرا رہے۔"]))
recs.append(R(6548471,"کالی پھلیوں کی ٹکیاں ہرے دھنیے اور لائم کے ساتھ","ہلکا پھلکا گرمیوں کا برگر تلاش کر رہے ہیں؟ کالی پھلیوں کی یہ ٹکیاں سالم اناج کے بن میں، سلاد کے اوپر، یا بس قتلوں میں کٹی پیاز کے ساتھ پلیٹ میں مزیدار لگتی ہیں۔","10","1 (4 اونس) ٹکی",
["1 کھانے کا چمچ زیتون کا تیل","1 کپ پیاز (کٹی ہوئی)","1/2 کپ ہری شملہ مرچ (کٹی ہوئی)","1/2 کپ لال شملہ مرچ (کٹی ہوئی)","1 ہالاپینو مرچ (باریک کٹی ہوئی)","2 جوے لہسن (باریک کٹے ہوئے)","1 چائے کا چمچ لال مرچ پاؤڈر (چلی پاؤڈر)","1/2 چائے کا چمچ خشک اوریگانو","1/2 چائے کا چمچ پسا ہوا زیرہ","1 ڈبہ کم سوڈیم والی کالی پھلیاں (16 اونس کا ڈبہ، پانی نہ نکالیں)","1 کپ ڈبل روٹی کا چورا (بغیر مسالے کے)","1/4 کپ، اور چھڑکنے کے لیے مزید مکئی کا آٹا (پیلا یا سفید)","1 کھانے کا چمچ لائم کا رس","1 چائے کا چمچ لائم کا چھلکا","3/4 چائے کا چمچ نمک","1/4 کپ چیڈر پنیر (کم چکنائی والا، یا کم چکنائی والا پیپر جیک پنیر استعمال کریں)","2 کھانے کے چمچ ہرا دھنیا (باریک کٹا ہوا)","1 اسپرے، 0.25 گرام نان اسٹک کوکنگ اسپرے (اسکوپ یا ناپنے والے کپ کے لیے)"],
["ایک بڑے نان اسٹک پین میں زیتون کا تیل گرم کریں اور پیاز، مرچیں، لہسن اور مسالے سوتے کریں۔ 3 منٹ سوتے کریں، یا جب تک سبزیاں نرم نہ ہو جائیں۔","کالی پھلیاں ان کے رس سمیت ڈالیں اور سبزیوں کے ساتھ 1 منٹ سوتے کریں۔ آنچ سے ہٹا لیں۔ ڈبل روٹی کا چورا، مکئی کا آٹا، لائم کا رس، لائم کا چھلکا اور نمک ملائیں۔ پھلیوں کے مرکب میں سے 1 کپ نکالیں اور بلینڈر یا فوڈ پروسیسر میں موٹی پیوری بننے تک پیس لیں۔ پیوری کو واپس پھلیوں کے مرکب میں ملا دیں۔ چیڈر پنیر اور ہرا دھنیا ڈال کر اچھی طرح ملائیں۔ مرکب موٹے پیسٹ جیسا ہونا چاہیے اور اتنا سخت کہ اسکوپ یا چمچ میں ٹھہر سکے۔","آئس کریم اسکوپ یا 1/3 کپ کے ناپنے والے کپ سے 3–4 اونس کے حصے بنائیں۔ (مرکب آسانی سے نکالنے کے لیے آئس کریم اسکوپ یا ناپنے والے کپ پر ہلکا سا کوکنگ اسپرے کریں) ایک پلیٹ پر مکئی کا آٹا چھڑکیں اور اسکوپ کیے ہوئے کالی پھلیوں کے حصے پلیٹ پر رکھیں۔ کالی پھلیوں کے مرکب پر ہلکا سا مکئی کا آٹا چھڑکیں اور آہستگی سے دبا کر ٹکی کی شکل دیں۔","اوون کو 375°F پر پہلے سے گرم کریں۔ ایک بڑے نان اسٹک پین پر سبزیوں کے تیل کا اسپرے کریں۔ ٹکیوں کو ہر طرف 2 منٹ بھورا کریں۔ اگر پین اوون میں رکھنے کے قابل ہو تو اسے اوون میں منتقل کریں اور 15 منٹ بیک کریں یا جب تک اندر تک گرم نہ ہو جائے۔ یا ٹکیوں کو کوکی شیٹ پین پر منتقل کر کے بیک کریں۔"]))
recs.append(R(6549589,"چیری اوٹ کرسپ","چیری اوٹ کرسپ ایک دلکش میٹھا ہے جو میٹھی اور کھٹی چیریوں کو کرکرے جئی (اوٹس) کے ٹاپنگ کے ساتھ ملاتا ہے۔ یہ زیادہ صحت مند ورژن ذیابیطس کے لیے موزوں ہے تاکہ ہر کوئی اس سے لطف اٹھا سکے۔","6","1/2 کپ",
["3 کپ چیریاں (تازہ یا منجمد، گٹھلی نکلی ہوئی)","1 کھانے کا چمچ لیموں کا رس","3 کھانے کے چمچ بغیر چینی کا میپل نما سیرپ","1 چائے کا چمچ ونیلا ایکسٹریکٹ","3/4 کپ پرانے طرز کے رولڈ اوٹس","1/4 کپ بادام کا آٹا","1/4 کپ اخروٹ (کٹے ہوئے)","2 کھانے کے چمچ سبزیوں کا تیل (پگھلا ہوا)","1/4 چائے کا چمچ نمک"],
["اوون کو 350 ڈگری F پر پہلے سے گرم کریں۔ 9 x 9 انچ کی بیکنگ ڈش پر پارچمنٹ پیپر بچھا دیں۔","ایک پیالے میں گٹھلی نکلی چیریاں، لیموں کا رس، زیرو کیلوری میپل سیرپ اور ونیلا ایکسٹریکٹ ملائیں۔ چیریوں پر اچھی طرح لگنے تک ملا دیں۔","چیریاں تیار بیکنگ ڈش میں ڈالیں اور برابر تہہ میں پھیلا دیں۔","الگ پیالے میں اوٹس، بادام کا آٹا، کٹے ہوئے میوے، سبزیوں کا تیل اور نمک ملائیں۔ مرکب کے بھربھرا ہونے تک ہلائیں۔","اوٹس کا مرکب چیریوں کے اوپر برابر چھڑکیں۔","تقریباً 30 منٹ بیک کریں یا جب تک چیری کی بھرائی میں بلبلے نہ اٹھیں اور اوٹس کی اوپری تہہ سنہری بھوری نہ ہو جائے۔","پیش کرنے سے پہلے 10 منٹ ٹھنڈا ہونے دیں۔","گرم پیش کریں۔"]))
recs.append(R(6549802,"اسموکی کالی پھلیوں کا ڈپ","ہمارے اسموکی کالی پھلیوں کے ڈپ کے ساتھ ذائقے کی جنت میں غوطہ لگائیں، ایک چٹپٹا احساس جو عام کالی پھلیوں کو دھواں دار جشن میں بدل دیتا ہے۔ اس ڈپ کو تازہ سبزیوں کے ساتھ پیش کریں، جو ایک صحت بخش، کم کاربوہائیڈریٹ والا ناشتہ یا اسٹارٹر ہے اور ذیابیطس والے اور بغیر ذیابیطس والے دونوں کے لیے بہترین ہے۔","6","1/4 کپ ڈپ + 1/2 کپ قتلوں میں کٹا کھیرا اور شملہ مرچ",
["1 ڈبہ (15 اونس) کالی پھلیاں (بغیر نمک اضافے کے، پانی نکالی ہوئی اور دھوئی ہوئی)","2 جوے لہسن (باریک کٹے ہوئے)","2 کھانے کے چمچ لائم کا رس","1 چائے کا چمچ پسا ہوا زیرہ","1/2 چائے کا چمچ اسموکڈ پیپریکا","1/2 چائے کا چمچ نمک","1/4 چائے کا چمچ کالی مرچ","1 کھانے کا چمچ زیتون کا تیل","2 کھانے کے چمچ سادہ بغیر چکنائی والا یونانی دہی","3 کپ کھیرا (قتلوں میں کٹا ہوا)","3 کپ لال شملہ مرچ (قتلوں میں کٹی ہوئی)"],
["فوڈ پروسیسر میں پانی نکالی اور دھوئی ہوئی کالی پھلیاں، باریک کٹا لہسن، کٹا ہوا تازہ ہرا دھنیا، لائم کا رس، پسا زیرہ، اسموکڈ پیپریکا، نمک اور کالی مرچ ملائیں۔ ہموار اور کریمی ساخت بننے تک بلینڈ کریں۔ اپنی پسندیدہ ساخت کے لیے بلینڈ کرتے وقت آپ آہستہ آہستہ 1 کھانے کا چمچ زیتون کا تیل ڈال سکتے ہیں۔ اپنی پسند کے مطابق تیل کی مقدار بے جھجھک ایڈجسٹ کریں۔","بلینڈ کرنے کے بعد ڈپ چکھیں اور مسالوں میں ضروری ردوبدل کریں۔ اپنے ذائقے کے مطابق مزید نمک، کالی مرچ یا لائم کا رس ڈال سکتے ہیں۔","کالی پھلیوں کا ڈپ سرونگ باؤل میں منتقل کریں اور اس میں 2 کھانے کے چمچ سادہ یونانی دہی آہستگی سے گھما کر ملائیں۔ یہ اضافہ ڈپ کو کریمی پن اور ذرا سی کھٹاس دیتا ہے۔","قتلوں میں کٹے کھیرے اور شملہ مرچ کے ساتھ پیش کریں۔"]))
recs.append(R(6549854,"گرِل کیے ہوئے پورٹابیلا ٹماٹر اور ٹسکن جڑی بوٹیوں کے ساتھ","یہ مزیدار مشروم تازہ موزاریلا یا پروولون پنیر کے ایک سلائس کے ساتھ اور سالم اناج کی ڈبل روٹی پر پیش کیے جانے والے لذیذ سینڈوچ بناتے ہیں۔ ساتھ میں ملی جلی ہری پتیوں کا سلاد پیش کریں۔","6","1 مشروم کیپ",
["1/4 کپ ایکسٹرا ورجن زیتون کا تیل","2 کھانے کے چمچ لیموں کا رس","2 کھانے کے چمچ بالسامک سرکہ","1 کھانے کا چمچ تازہ اوریگانو (باریک کٹا ہوا)","1 ٹہنی تازہ روزمیری (باریک کٹی ہوئی)","2 کھانے کے چمچ تلسی (باریک کٹی ہوئی)","2 جوے لہسن (باریک کٹے ہوئے)","1/2 کپ ٹماٹر (کٹے ہوئے)","1/2 چائے کا چمچ کالی مرچ","6 عدد پورٹوبیلو مشروم (صاف کپڑے سے پونچھے ہوئے اور ڈنٹھل ہٹائے ہوئے)"],
["میرینیڈ کے تمام اجزاء ایک درمیانے پیالے میں ملائیں اور ایک بڑے مضبوطی سے بند ہونے والے پلاسٹک بیگ میں ڈال دیں۔ بہترین نتائج کے لیے مشروم کیپس کو کمرے کے درجہ حرارت پر کم از کم 15-30 منٹ میرینیٹ کریں۔","گرِل کو درمیانی تیز پر پہلے سے گرم کریں اور مشروم کیپس کو گرِل کی جالی پر رکھیں۔ براہ راست حرارت کے نیچے ہر طرف 5 منٹ پکائیں جب تک پوری طرح اندر تک نرم نہ ہو جائیں۔ پکاتے وقت کبھی کبھار مزید میرینیڈ لگاتے رہیں۔ پیش کرنے سے پہلے بچا ہوا میرینیڈ مشروم پر ڈال سکتے ہیں۔"]))
